/**
 * Chart palette.
 *
 * figma: `chart-1..5` in the `mode` collection are aliases onto the Radix
 * `blue` scale, steps 8 → 12 (rdx/colors collection). That is a sequential
 * ramp, not a categorical one: use it in order for ordered series, and reach
 * for `radixScales` below when you need categorically distinct series.
 */
export const chartColors = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
] as const;

/** Light-mode hexes, for exports that cannot resolve CSS variables. */
export const chartColorsLight = ["#5eb1ef", "#0090ff", "#0588f0", "#0d74ce", "#113264"] as const;
/** Radix `blueDark` steps 8 → 12. */
export const chartColorsDark = ["#2870bd", "#0090ff", "#3b9eff", "#70b8ff", "#c2e6ff"] as const;

export function chartColor(index: number) {
  return chartColors[index % chartColors.length];
}
